mapper.update:
UPDATE ifj_notification_outbox
SET lease_deadline = TIMESTAMPADD(MICROSECOND, #{leaseMicros}, CURRENT_TIMESTAMP(3)),
    update_time = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND lease_deadline > CURRENT_TIMESTAMP(3)

UPDATE ifj_notification_outbox
SET lease_deadline = (CURRENT_TIMESTAMP(3) + (#{leaseMicros} * INTERVAL '1 microsecond')),
    update_time = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND lease_deadline > CURRENT_TIMESTAMP(3)

UPDATE ifj_notification_outbox
SET lease_deadline = strftime('%Y-%m-%d %H:%M:%f','now', printf('+%.6f seconds', (#{leaseMicros} / 1000000.0))),
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
WHERE id = #{id}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now')

UPDATE ifj_notification_outbox
SET lease_deadline = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) + NUMTODSINTERVAL(#{leaseMicros} / 1000000, 'SECOND'),
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE id = #{id}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))

UPDATE ifj_notification_outbox
SET lease_deadline = DATEADD(MILLISECOND, (#{leaseMicros} / 1000), SYSUTCDATETIME()),
    update_time = SYSUTCDATETIME()
WHERE id = #{id}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND lease_deadline > SYSUTCDATETIME()
